import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type DataFlowProps = Record<string, any>;

const DataFlow: React.FC<DataFlowProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  gridColor = "#333333",
  gridOpacityVal = 0.6,
  leftLabel = "Demand",
  rightLabel = "Capacity",
  leftBarColor = "#8c1014",
  rightBarColor = "#3a3a3a",
  labelColor = "#ffffff",
}) => {
  
  {/* Load Google Fonts */}
  useFontLoader(["Bebas Neue"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Prevent parser errors for transparent background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive layout calculations
  const s = Math.min(width, height);
  const gridCellSize = Math.max(20, Math.round(s * 0.037)); 
  const barHeight = gridCellSize * 2;
  const maxBarWidth = gridCellSize * 11;
  
  // Ensure the grid is large enough to span the center gracefully
  const gridCols = 30; 
  const gridRows = 16;
  const gridContainerWidth = gridCols * gridCellSize;
  const gridContainerHeight = gridRows * gridCellSize;

  // Timings and Animations (Slower configuration)
  const gridOpacityAnim = interpolate(frame, [0, 40], [0, 1], { extrapolateRight: "clamp" });
  
  // Staggered springs for a mechanical flow, adjusted for slower motion
  const bar1Progress = spring({ fps, frame: frame - 20, config: { damping: 20, mass: 1.5, stiffness: 60 } });
  const bar2Progress = spring({ fps, frame: frame - 40, config: { damping: 20, mass: 1.5, stiffness: 60 } });

  const rightBarWidth = bar1Progress * maxBarWidth;
  const leftBarWidth = bar2Progress * maxBarWidth;

  // Outro animation based on duration
  const exitStartFrame = durationInSeconds * fps - 30;
  const exitOpacity = interpolate(frame, [exitStartFrame, exitStartFrame + 20], [1, 0], { 
    extrapolateLeft: 'clamp', 
    extrapolateRight: 'clamp' 
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "'Bebas Neue', sans-serif", opacity: exitOpacity }}>
      
      {/* Center Aligned Grid with Radial Mask */}
      <div style={{
        position: 'absolute',
        top: '50%',
        left: '50%',
        transform: 'translate(-50%, -50%)',
        width: gridContainerWidth,
        height: gridContainerHeight,
        backgroundImage: `
          linear-gradient(to right, ${gridColor} 1px, transparent 1px),
          linear-gradient(to bottom, ${gridColor} 1px, transparent 1px)
        `,
        backgroundSize: `${gridCellSize}px ${gridCellSize}px`,
        backgroundPosition: 'top left',
        opacity: gridOpacityVal * gridOpacityAnim,
        maskImage: 'radial-gradient(ellipse at center, rgba(0,0,0,1) 10%, rgba(0,0,0,0) 70%)',
        WebkitMaskImage: 'radial-gradient(ellipse at center, rgba(0,0,0,1) 10%, rgba(0,0,0,0) 70%)',
        transition: 'none',
      }} />

      {/* Top Bar (Right-facing - Capacity) */}
      <div style={{
        position: 'absolute',
        top: height / 2 - barHeight,
        left: width / 2,
        width: rightBarWidth,
        height: barHeight,
        backgroundColor: rightBarColor,
        transformOrigin: 'left center',
        transition: 'none',
      }} />

      {/* Bottom Bar (Left-facing - Demand) */}
      <div style={{
        position: 'absolute',
        top: height / 2,
        right: width / 2,
        width: leftBarWidth,
        height: barHeight,
        backgroundColor: leftBarColor,
        transformOrigin: 'right center',
        transition: 'none',
      }} />

      {/* Right Label (Capacity) */}
      <div style={{
        position: 'absolute',
        top: height / 2 - barHeight,
        left: width / 2 + rightBarWidth + gridCellSize,
        height: barHeight,
        display: 'flex',
        alignItems: 'center',
        color: labelColor,
        fontSize: gridCellSize * 1.5,
        fontWeight: 400,
        opacity: interpolate(bar1Progress, [0.4, 0.9], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }),
        transform: `translateX(${interpolate(bar1Progress, [0.4, 1], [-20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' })}px)`,
        transition: 'none',
      }}>
        {rightLabel}
      </div>

      {/* Left Label (Demand) */}
      <div style={{
        position: 'absolute',
        top: height / 2,
        right: width / 2 + leftBarWidth + gridCellSize,
        height: barHeight,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'flex-end',
        color: labelColor,
        fontSize: gridCellSize * 1.5,
        fontWeight: 400,
        opacity: interpolate(bar2Progress, [0.4, 0.9], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }),
        transform: `translateX(${interpolate(bar2Progress, [0.4, 1], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' })}px)`,
        transition: 'none',
      }}>
        {leftLabel}
      </div>

    </AbsoluteFill>
  );
};

export default DataFlow;